widget.solution:
import numpy as np

def ensemble_predict(trees, x_query):
    X = np.asarray(x_query, dtype=float).reshape(-1, 1)
    total = np.zeros(len(X))
    for tree in trees:
        total = total + tree.predict(X)
    return np.round(total, 4)
